INSERT INTO public.services (slug, name, category, garment_type, short_description, long_description, base_price, stitching_days, image_url, featured, sort_order) VALUES
('saree-blouse','Saree Blouse Stitching','Blouse','BLOUSE','Perfectly fitted saree blouses with your choice of neck, sleeve and back design.','Our signature service. Every saree blouse is drafted from your own measurements, with a trial fitting before final finishing. Choose from princess cut, katori, padded or non-padded, and over 40 neck and back designs.',1200,7,'/images/service-blouse.jpg',true,1),
('designer-blouse','Designer Blouse','Blouse','BLOUSE','Statement blouses with embroidery, latkans, lace and mirror work.','Hand-finished designer blouses combining zari, sequin, dori and mirror work. Ideal for festive sarees and family functions.',2600,10,'/images/service-blouse.jpg',true,2),
('bridal-lehenga-blouse','Bridal Lehenga Blouse','Bridal','BLOUSE','Heavily worked bridal blouses engineered for all-day comfort.','Structured bridal blouses with canvas support, boning where required, hook-and-eye closures and full lining, so heavy embroidery never compromises comfort.',5500,21,'/images/hero-bridal.jpg',true,3),
('suit','Suit Stitching','Ethnic','SUIT','Classic straight and A-line suits tailored to your fit.','Straight, A-line or panelled suits with your preferred neck, sleeve and slit. Trouser, churidar or palazzo bottom included.',1500,8,'/images/service-anarkali.jpg',false,4),
('salwar-suit','Salwar Suit','Ethnic','SUIT','Traditional salwar suit with kameez, salwar and dupatta finishing.','Comfortable everyday and festive salwar suits, drafted with generous ease and reinforced seams for daily wear.',1650,8,'/images/service-anarkali.jpg',false,5),
('anarkali','Anarkali','Ethnic','SUIT','Flared Anarkali silhouettes from panel to full-circle.','Choose 6, 8, 12 or full-circle flare, floor length or ankle length, with optional inner canfan for volume.',2800,12,'/images/service-anarkali.jpg',true,6),
('kurti','Kurti','Ethnic','SUIT','Everyday and office kurtis in your exact fit.','Straight, A-line, angrakha or asymmetric kurtis with your choice of neckline and sleeve.',950,6,'/images/service-anarkali.jpg',false,7),
('sharara','Sharara Set','Ethnic','SUIT','Sharara sets with flowing pleated bottoms.','Sharara sets with kalidar or gathered bottoms, matched kurta and dupatta finishing.',3200,12,'/images/service-anarkali.jpg',false,8),
('palazzo','Palazzo','Ethnic','SUIT','Palazzos, pants and churidars stitched to length.','Wide-leg palazzos, cigarette pants, dhoti pants and churidars, all cut to your waist-to-floor measurement.',700,5,'/images/service-kurti.jpg',false,9),
('gown','Gown','Gown','GOWN','Elegant gowns for receptions and evening events.','Fitted-bodice or empire-line gowns with concealed zip, lining and optional trail.',3400,14,'/images/service-gown.jpg',true,10),
('designer-gown','Designer Gown','Gown','GOWN','Couture gowns with structured bodices and hand embellishment.','Fully structured couture gowns with corseted bodice, hand-set sequins and crystal work, plus two fitting sessions.',7500,21,'/images/service-gown.jpg',true,11),
('western-dress','Western Dress','Western','DRESS','Bodycon, A-line, wrap and shift dresses.','Western dresses drafted from Indian body blocks for a fit that actually sits right, with proper lining and finishing.',2200,10,'/images/service-gown.jpg',false,12),
('party-wear','Party Wear','Occasion','DRESS','Cocktail and party outfits with an edge.','Party-ready silhouettes in georgette, satin and velvet with subtle shimmer detailing.',3000,12,'/images/service-gown.jpg',false,13),
('wedding-wear','Wedding Wear','Wedding','LEHENGA','Complete wedding-guest and family outfits.','Lehengas, shararas and gowns for the wedding party, colour-coordinated across the family if needed.',6500,25,'/images/hero-bridal.jpg',true,14),
('bridal-wear','Bridal Wear','Bridal','LEHENGA','Full bridal lehengas made over a guided timeline.','A dedicated bridal journey: consultation, fabric curation, three fittings and final delivery two weeks before the date.',22000,45,'/images/hero-bridal.jpg',true,15),
('bridesmaid-dress','Bridesmaid Dress','Wedding','DRESS','Coordinated bridesmaid outfits in matching palettes.','Batch-stitched bridesmaid outfits with individual measurements and a single coordinated palette.',3800,18,'/images/service-gown.jpg',false,16),
('reception-outfit','Reception Outfit','Wedding','GOWN','Reception gowns and lehengas with a modern edge.','Statement reception looks: draped gowns, cape lehengas and pre-stitched saree gowns.',9500,28,'/images/service-gown.jpg',false,17),
('engagement-outfit','Engagement Outfit','Wedding','LEHENGA','Engagement lehengas and suits in lighter palettes.','Lighter, ring-ceremony-appropriate silhouettes in pastels with fine tone-on-tone work.',7800,24,'/images/service-anarkali.jpg',false,18),
('haldi-outfit','Haldi Outfit','Wedding','SUIT','Comfortable, colourful haldi outfits.','Marigold and mustard palettes in breathable cotton silk, cut for movement and easy washing.',3200,14,'/images/service-anarkali.jpg',false,19),
('mehendi-outfit','Mehendi Outfit','Wedding','SUIT','Mehendi lehengas, shararas and suits.','Mirror-work and gota patti mehendi looks with wide sleeves that stay clear of fresh henna.',4200,16,'/images/service-anarkali.jpg',false,20),
('sangeet-outfit','Sangeet Outfit','Wedding','LEHENGA','Dance-ready sangeet outfits.','Lightweight, movement-tested sangeet outfits with secure fastenings and stretch panels.',5600,18,'/images/hero-bridal.jpg',false,21),
('custom-designer-outfit','Custom Designer Outfit','Custom','OTHER','Bring a reference or an idea and we draft it.','Full custom design service. Share a picture, a sketch or just a description, and our designers create a tech pack, sample fit and final garment.',8500,30,'/images/atelier-embroidery.jpg',true,22),
('alterations','Alterations','Alteration','OTHER','Resizing, hemming, re-fitting and repairs.','Take-in, let-out, hemming, sleeve changes, zip replacement and full re-fitting of existing garments.',350,3,'/images/atelier-embroidery.jpg',false,23),
('embroidery','Embroidery & Handwork','Custom','OTHER','Zari, zardosi, sequin, mirror, gota and thread work.','Hand and machine embroidery on your fabric or ours, priced by panel and density.',1800,15,'/images/atelier-embroidery.jpg',true,24),
('customization','Customization Add-ons','Custom','OTHER','Padding, lining, lace, borders, tassels and more.','Add padding, lining, hooks, zippers, lace, borders, sequins, buttons and tassels to any garment.',250,3,'/images/atelier-embroidery.jpg',false,25);
