INSERT INTO public.reviews (customer_name, city, rating, comment, garment, approved) VALUES
('Ananya Sharma','Surat',5,'My bridal lehenga fit like it was drawn on me. Three fittings, zero stress, delivered two weeks early.','Bridal Lehenga',true),
('Priya Mehta','Ahmedabad',5,'Finally a blouse that fits properly at the armhole. I have ordered six more since.','Saree Blouse',true),
('Rhea Kapoor','Mumbai',5,'The designer gown was better than the reference photo I sent. Beautiful finishing inside and out.','Designer Gown',true),
('Sneha Patel','Vadodara',4,'Lovely anarkali and very patient with my design changes. Delivery was a day late but worth it.','Anarkali',true),
('Divya Nair','Pune',5,'Home measurement appointment was so convenient. The staff were professional and quick.','Salwar Suit',true),
('Meera Joshi','Rajkot',5,'They matched my mother''s old saree border into my new blouse. Truly thoughtful work.','Designer Blouse',true),
('Kavya Reddy','Hyderabad',5,'Ordered coordinated outfits for five bridesmaids. Every single fit was spot on.','Bridesmaid Dress',true),
('Isha Agarwal','Delhi',4,'Great embroidery quality and clear order tracking throughout.','Embroidery',true);
INSERT INTO public.faqs (question, answer, category, sort_order) VALUES
('How long does stitching take?','Everyday garments take 5-8 days, designer pieces 12-21 days, and full bridal outfits 30-45 days. The exact date is shown before you confirm your order.','Orders',1),
('Can I give my own fabric?','Yes. Choose "I will provide the fabric" during your custom order and we will confirm the required metres for your garment.','Fabric',2),
('Do you take measurements at home?','Yes. Book a professional measurement appointment at home or at our store, and choose a date and time slot that suits you.','Measurements',3),
('What if the fit is not right?','Every order includes one free alteration within 10 days of delivery. Bridal orders include three fitting sessions.','Alterations',4),
('How do I pay?','Payments are currently processed in demo mode inside the site. Card details are never stored.','Payments',5),
('Can I track my order?','Yes. Every order has a live timeline from Order Placed through to Delivered inside your dashboard.','Orders',6),
('Do you ship across India?','Yes, we deliver across India. Delivery charges are shown before you confirm.','Delivery',7),
('Can I cancel an order?','Orders can be cancelled free of charge before cutting begins. After cutting, fabric and labour costs apply.','Refunds',8),
('Do you do alterations on outside garments?','Yes, we alter garments stitched elsewhere, priced from Rs 350 depending on the work.','Alterations',9),
('How accurate should my measurements be?','Measure over light clothing with a soft tape and keep it snug. Our guided instructions show exactly where to place the tape for each field.','Measurements',10);
